"""Structured army-book data for the 2026 beta faction expansion.

The permanent English keys are implementation identifiers only.  Display names,
profiles, costs, and concise rule summaries come from the user-supplied Chinese
army books listed in SOURCES.md.
"""

from __future__ import annotations


def unit(
    key: str,
    name: str,
    page: int,
    category: str,
    cost: int,
    global_profile: tuple[str, ...],
    defence: tuple[str, ...],
    offence: list[tuple[str, ...]],
    **extra: object,
) -> dict[str, object]:
    return {
        "key": key,
        "name": name,
        "page": page,
        "category": category,
        "cost": cost,
        "global": global_profile,
        "defence": defence,
        "offence": offence,
        **extra,
    }


